const form=document.querySelector('#project-form');const status=document.querySelector('#form-status');form.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form).entries());localStorage.setItem('waika-project-draft',JSON.stringify({...data,savedAt:new Date().toISOString()}));status.textContent='Briefing guardado como borrador. La recepción conectada se activará en la siguiente fase.';status.className='form-status ok';});
